--
-- Table structure for table `delete_players`
--

DROP TABLE IF EXISTS `delete_players`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `delete_players` (
  `id` int NOT NULL AUTO_INCREMENT,
  `player` varchar(255) NOT NULL,
  `bday` date NOT NULL,
  `rank` int NOT NULL,
  `city` varchar(255) NOT NULL,
  `region` varchar(255) NOT NULL,
  `razryad` varchar(10) NOT NULL,
  `coach_id` int NOT NULL,
  `full_name` varchar(255) NOT NULL,
  `title_id` int NOT NULL,
  `pay_rejting` varchar(50) NOT NULL,
  `comment` varchar(255) NOT NULL,
  `patronymic_id` int NOT NULL,
  `sex` varchar(10) DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `delete_player_coach_id` (`coach_id`),
  KEY `delete_player_title_id` (`title_id`),
  CONSTRAINT `delete_players_ibfk_1` FOREIGN KEY (`coach_id`) REFERENCES `coachs` (`id`),
  CONSTRAINT `delete_players_ibfk_3` FOREIGN KEY (`title_id`) REFERENCES `titles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=544 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

