--
-- Table structure for table `game_lists`
--

DROP TABLE IF EXISTS `game_lists`;
/*!40101 SET @saved_cs_client     = @@character_set_client */;
/*!50503 SET character_set_client = utf8mb4 */;
CREATE TABLE `game_lists` (
  `id` int NOT NULL AUTO_INCREMENT,
  `number_group` varchar(255) NOT NULL,
  `rank_num_player` int NOT NULL,
  `player_group_id` int DEFAULT NULL,
  `system_id` int NOT NULL,
  `title_id` int NOT NULL,
  `sex` varchar(10) DEFAULT NULL,
  `player_double_id` int DEFAULT NULL,
  `team_id` int DEFAULT NULL,
  PRIMARY KEY (`id`),
  KEY `game_list_player_group_id` (`player_group_id`),
  KEY `game_list_system_id` (`system_id`),
  KEY `game_list_title_id` (`title_id`),
  KEY `game_lists_team_id` (`team_id`),
  CONSTRAINT `fk_game_lists_team_id_refs_teams` FOREIGN KEY (`team_id`) REFERENCES `teams` (`id`),
  CONSTRAINT `game_lists_ibfk_1` FOREIGN KEY (`player_group_id`) REFERENCES `players` (`id`),
  CONSTRAINT `game_lists_ibfk_2` FOREIGN KEY (`system_id`) REFERENCES `system` (`id`),
  CONSTRAINT `game_lists_ibfk_3` FOREIGN KEY (`title_id`) REFERENCES `titles` (`id`)
) ENGINE=InnoDB AUTO_INCREMENT=40822 DEFAULT CHARSET=utf8mb4 COLLATE=utf8mb4_0900_ai_ci;
/*!40101 SET character_set_client = @saved_cs_client */;

