CREATE TABLE `teams` (
  `id` int NOT NULL AUTO_INCREMENT,
  `team_name` varchar(70) NOT NULL,
  `region` varchar(255) DEFAULT NULL,
  `coach_team` varchar(255) DEFAULT NULL,
  `r_sum` int NOT NULL,
  `title_id` int DEFAULT NULL,
  `id_pl1` int DEFAULT NULL,
  `r_pl1` int NOT NULL,
  `id_pl2` int DEFAULT NULL,
  `r_pl2` int NOT NULL,
  `id_pl3` int DEFAULT NULL,
  `r_pl3` int NOT NULL,
  `id_pl4` int DEFAULT NULL,
